// lib/MessageRequestSerializer.ts
import { Client } from "@vonage/server-client";
var messageRequestSerializer = (params) => {
  const data = Client.transformers.snakeCaseObjectKeys(params, true);
  const channel = params?.channel;
  switch (channel) {
    case "rcs" /* RCS */:
      if ("custom" in data) {
        data.custom = params.custom;
      }
      break;
    case "email" /* EMAIL */:
      if ("email" in data && Array.isArray(data.email.cc) && data.email.cc.length < 1) {
        data.email.cc = void 0;
      }
      if ("email" in data && Array.isArray(data.email.bcc) && data.email.bcc.length < 1) {
        data.email.bcc = void 0;
      }
      break;
    default:
      break;
  }
  return data;
};

export {
  messageRequestSerializer
};
